package webui

const awsPageTemplate = `
{{define "aws"}}<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>AWS EC2 · Aiori Compute</title>{{template "styles" .}}</head><body class="app-body"><a class="skip-link" href="#main-content">Skip to main content</a><div class="app-shell">{{template "sidebar" .}}<main class="main-area" id="main-content"><header class="topbar"><div class="breadcrumbs">Infrastructure / <strong>AWS EC2</strong></div><span class="env-pill">EXPLICIT CLOUD ACTIONS</span></header><div class="content"><div class="page-heading"><div><div class="eyebrow">Cloud infrastructure</div><h1>Launch an EC2 test node</h1><p>Create a small, tagged EC2 instance for Linux bootstrap and controller connectivity testing.</p></div></div>{{if .Notice}}<div class="notice" role="status">{{.Notice}}</div>{{end}}{{if .Error}}<div class="notice error" role="alert">{{.Error}}</div>{{end}}<div class="dashboard-grid"><section class="section-card"><div class="section-head"><div><h2 class="section-title">Launch configuration</h2><div class="section-subtitle">Uses credentials configured on the controller host</div></div></div><form method="post" action="/aws/instances" class="form-stack"><input type="hidden" name="csrf_token" value="{{.CSRFToken}}"><input type="hidden" name="client_token" value="{{.IdempotencyKey}}"><div class="field"><label for="ec2-name">Instance name</label><input id="ec2-name" name="name" required maxlength="128" pattern="[A-Za-z0-9][A-Za-z0-9 _.-]*" value="aiori-worker-test"></div><div class="field"><label for="ec2-region">AWS region</label><input id="ec2-region" name="region" required value="{{.Region}}" placeholder="ap-south-1"></div><div class="field"><label for="ec2-type">Instance type</label><select id="ec2-type" name="instance_type"><option value="t3.micro">t3.micro · connectivity test</option><option value="t3.small">t3.small · larger connectivity test</option></select></div><div class="field"><label for="ec2-ami">AMI ID</label><input id="ec2-ami" name="image_id" required placeholder="ami-0123456789abcdef0"></div><div class="field"><label for="ec2-subnet">Subnet ID</label><input id="ec2-subnet" name="subnet_id" required placeholder="subnet-0123456789abcdef0"></div><div class="field"><label for="ec2-sg">Existing security group IDs</label><input id="ec2-sg" name="security_group_ids" required placeholder="sg-0123456789abcdef0"><div class="field-help">Comma or space separated. Configure inbound rules first; restrict SSH and worker-agent traffic to trusted sources only.</div></div><div class="field"><label for="ec2-key">EC2 key pair name (optional)</label><input id="ec2-key" name="key_name" placeholder="admin-key"></div><div class="field"><label for="ec2-profile">Instance profile name (optional)</label><input id="ec2-profile" name="instance_profile" placeholder="aiori-worker-ssm"></div><button class="btn btn-primary" type="submit">Launch one EC2 instance</button></form></section><section class="section-card"><div class="section-head"><div><h2 class="section-title">Important before launch</h2><div class="section-subtitle">Network and compute safety</div></div></div><div class="callout">The controller never creates or widens security groups. Use a preconfigured security group that permits the agent port only from the controller's trusted address or security group.</div><p class="section-subtitle">The initial workflow creates an EC2 instance only. It does not install the worker agent or register the machine automatically. A t3.micro is not a KVM/Cloud Hypervisor compute host; treat it as a bootstrap and connectivity test node.</p><p class="section-subtitle">AWS lifecycle state is authoritative and separate from agent heartbeat health. Start and stop are available after launch. Termination is intentionally not exposed in this first workflow.</p><a href="/workers">Continue to worker inventory →</a></section></div>{{if .HasInstance}}<section class="section-card"><div class="section-head"><div><h2 class="section-title">EC2 instance</h2><div class="section-subtitle">Read from the selected AWS region</div></div><span class="status">{{.Instance.State.Name}}</span></div><p><strong>{{.Instance.ID}}</strong> · {{.Instance.Type}} · {{.Instance.Placement.AvailabilityZone}}</p><p>Private IP: {{.Instance.PrivateIP}} · Public IP: {{if .Instance.PublicIP}}{{.Instance.PublicIP}}{{else}}Not assigned{{end}}</p><div class="field-actions"><form method="post" action="/aws/instances/{{.Instance.ID}}/start"><input type="hidden" name="csrf_token" value="{{.CSRFToken}}"><input type="hidden" name="region" value="{{.Region}}"><button class="btn btn-primary" type="submit">Start instance</button></form><form method="post" action="/aws/instances/{{.Instance.ID}}/stop"><input type="hidden" name="csrf_token" value="{{.CSRFToken}}"><input type="hidden" name="region" value="{{.Region}}"><button class="btn btn-secondary" type="submit" onclick="return confirm('Stop this EC2 instance?');">Stop instance</button></form><a class="btn btn-secondary" href="/aws?instance_id={{.Instance.ID}}&region={{.Region}}">Refresh state</a></div></section>{{end}}</div></main></div><script src="/assets/ui.js" defer></script></body></html>{{end}}`
